export const tasks = [];
function task(id, section, title, steps, options = {}) {
  tasks.push({ id, section, title, steps: steps.map((text, i) => typeof text === 'object' ? { id: `${id}.${i + 1}`, ...text } : { id: `${id}.${i + 1}`, text }),
    requires: [], tags: [], priority: 500, branch: null, tier: 'Useful', location: 'See steps', reward: 'Progress recorded', why: 'Keep the next session focused.',
    time: '15–30 min', team: 'Solo', gate: 'None', sources: [], ...options });
}
