task('log-exotics', 'cleanup', 'Old catalysts and Exotic quests can wait', ['Park long catalysts for weapons you do not use. Work on Still Hunt’s optional catalyst naturally when it drops.', 'Save Spoils and Ciphers for a chosen purchase; do not buy every Monument to Lost Lights weapon before acquiring Nighthawk.', 'Keep deterministic dungeon / Exotic unlock quests if you plan to run with friends, but do not treat their reward as needed for this build.', 'Do not dismantle old Exotics for an assumed infusion cap. Inspect the current item and preserve useful catalysts / crafted weapons.'], { tags: ['Exotic', 'Optional'], requires: ['audit'], time: '5–10 min', reward: 'A small active quest list', sources: ['faq', 'cipher'] });

