export const glossary = {
  'RNG': 'Random outcome. Repeating an activity may not give the item or roll you want.',
  'Weekly gated': 'A reward or purchase has a weekly limit. Checking it here does not reset it in-game.',
  'Deepsight': 'A red-border weapon can grant progress toward its crafting pattern. Extract the pattern before dismantling.',
  'Armor Charge': 'A temporary resource commonly gained from Orbs. Surges use it over time; other mods may spend it.',
  'Radiant': 'A Solar outgoing weapon-damage buff. It is a buff on you, not a debuff on the boss.',
  'Debuff': 'An effect applied to a target, such as Slow, Sever, Scorch or Weaken. Aggregate Charge counts distinct elemental debuffs.',
  'DPS': 'Damage per second. A damage phase is the period when a boss is vulnerable.',
  'Tier': 'Gear quality. A good perk roll can matter more than tier, and weapon upgrading does not add new alternative perks.',
  'Exfil': 'Exit a Lawless job through its extraction point to bank completion and certain loot.',
  'Origin trait': 'An extra perk tied to a weapon’s source. Inspect it; a cosmetic ornament does not prove it is present.',
  'Aspect / Facet': 'Aspects define subclass behavior. Facets are Prismatic fragments that add smaller effects.',
  'Attunement': 'A preference for eligible rewards, chosen in Inventory. It does not make every activity drop the weapon.',
  'Build Critical': 'Needed for the functional route chosen here, including learning the rotation. It does not mean all such tasks are game-enforced unlocks.'
};

